<script setup lang="tsx">
import { ref, computed, watch, onMounted, onBeforeUnmount } from "vue";
import { useRoute } from "vue-router";
import router from "@/router";
import {
  GetProblemJudge,
  PostJudgeDataAi,
  GetJudgeDataAi,
  GetJudgeDataAiList,
  GetAiPreviewZip,
  PostJudgeDataAiApply,
  PostJudgeDataAiCancel,
  PostJudgeDataAiRetry,
} from "@/apis/problem.ts";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsError, ShowTextTipsSuccess } from "@/util/tips";
import { useWebStyleStore } from "@/stores/webStyle.ts";
import { AiTestdataJobView, AiTestdataStageView, AiTestdataLlmCallView } from "@/types/problem.ts";
import { GetFileSizeStr } from "@/util/file.ts";
import { useBreakpoint } from "@/composables/useBreakpoint";

let route = useRoute();
const { globalProperties } = useCurrentInstance();

const webStyleStore = useWebStyleStore();
const { isMobile } = useBreakpoint();

// ===== 题目信息（精简加载：仅取 id / 标题 / AI 开关 / 最近任务；权限由路由 auths 兜底） =====
const problemKey = ref("");
let problemId = 0;
const problemTitle = ref("");
const problemLoading = ref(false);
const aiEnabled = ref(false);

// ===== AI 生成测试数据 =====
const AI_STATUS_NAMES: Record<number, string> = {
  0: "等待开始",
  1: "排队中",
  2: "规划测试点",
  3: "撰写参考代码",
  4: "编译参考代码",
  5: "生成输入数据",
  6: "运行参考代码",
  7: "已完成",
  8: "生成失败",
  9: "已取消",
};

// AI 生成流程的固定步骤（发起前即可完整展示，供用户提前感知整条流水线）
type AiFlowStatus = "default" | "process" | "finish" | "error";
const AI_WORKFLOW: { title: string; content: string }[] = [
  { title: "规划测试点", content: "AI 阅读题面，设计测试点与分数分布" },
  { title: "撰写参考代码", content: "依据题面编写参考代码（标程）" },
  { title: "编译参考代码", content: "在沙箱中编译参考代码" },
  { title: "生成输入并运行", content: "生成输入数据并在沙箱中运行参考代码，产出标准输出" },
  { title: "生成完成", content: "可预览并应用为官方测试数据" },
];
// 每步对应的真实 stage 集合：第 4 步「生成输入并运行」合并后端 stage 5(生成输入) 与 6(运行参考代码)，
// 二者实际上是并行/同一时机进行，UI 合并为一个展示步，同时列出两段真实子阶段明细
const AI_STAGE_OF_STEP: number[][] = [[2], [3], [4], [5, 6], []];
// 生成一条「前 i 步完成、第 i 步进行中、其余未开始」的状态序列
const flowStats = (i: number): AiFlowStatus[] => AI_WORKFLOW.map((_, idx) => (idx < i ? "finish" : idx === i ? "process" : "default"));

// 根据任务状态把 5 步主流程映射为当前态：
// 无任务/排队/规划 → 第一步进行中；逐阶段前进点亮已完成步；
// 完成 → 全点亮；失败 → 定位到失败阶段并标红；取消 → 回到未开始
const aiWorkflowSteps = computed((): { title: string; content: string; status: AiFlowStatus }[] => {
  const job = aiJob.value;
  const L = AI_WORKFLOW.length;
  const statuses = (() => {
    const st = job?.status;
    switch (st) {
      case undefined:
        // 尚未创建任务：整条流程作为「即将发生」的纯预览展示，不点亮任何一步
        return AI_WORKFLOW.map(() => "default");
      case 0:
      case 1:
      case 2:
        return flowStats(0);
      case 3:
        return flowStats(1);
      case 4:
        return flowStats(2);
      case 5:
      case 6:
        // 生成输入(stage5) 与 运行参考代码(stage6) 合并为同一展示步
        return flowStats(3);
      case 7:
        return flowStats(L).map((s) => "finish" as AiFlowStatus);
      case 8: {
        // 失败：定位时间线里最后一个失败的阶段，标注为 error，之前步骤已完成
        const failStage = (job?.stages ?? [])
          .filter((s) => s.status === "fail")
          .map((s) => s.stage)
          .sort((a, b) => a - b)
          .pop();
        // 5 步映射：stage2→0, stage3→1, stage4→2, stage5/6→3
        const idx = typeof failStage === "number" ? Math.max(0, Math.min(3, failStage - 2)) : 2;
        return AI_WORKFLOW.map((_, i) => (i < idx ? "finish" : i === idx ? "error" : "default"));
      }
      case 9:
        return AI_WORKFLOW.map(() => "default");
      default:
        return flowStats(0);
    }
  })();
  return AI_WORKFLOW.map((w, i) => ({ ...w, status: statuses[i] }));
});

// 生成流水线 Timeline 条目：把固定 5 步流水线（AI_WORKFLOW）与真实阶段记录（job.stages）合并，
// 叠加 job.status 推断的点亮/占位状态，形成一条常驻贯穿全生命周期的流水线视图。
// 发起前整条「未开始」占位（提前感知未来任务）；进行中已发生阶段点亮真实状态，
// 未到阶段继续占位、随进度逐个「浮出」。第 4 步「生成输入并运行」承载 stage 5/6 两段真实子阶段
interface AiTimelineItem {
  step: number; // 步骤索引 0..4
  title: string;
  content: string;
  status: AiFlowStatus;
  stageRecs: AiTestdataStageView[]; // 真实子阶段记录（按 stage 升序）；running 时浅克隆以驱动实时刷新
  planCount?: number; // 仅「生成输入并运行」步：已规划的测试点总数
  progress?: { pct: number }; // 仅「生成输入并运行」步：生成+运行总体进度百分比（task_current 为 0-100，非点数）
}
const aiTimelineItems = computed<AiTimelineItem[]>(() => {
  const job = aiJob.value;
  if (job && job.status <= 6) void aiNow.value; // running：依赖 aiNow tick 重建，驱动 running 阶段耗时实时跳动
  const steps = aiWorkflowSteps.value;
  const stagesByStage = new Map((job?.stages ?? []).map((s) => [s.stage, s] as const));
  const running = job !== null && job.status <= 6;
  const taskTotal = job?.task_total ?? 0;
  return steps.map((w, i) => ({
    step: i,
    title: w.title,
    content: w.content,
    status: w.status,
    // 浅克隆 running 阶段记录：对象新身份强制 t-timeline-item 重渲染，让耗随时钟 100ms tick 实时更新
    stageRecs: AI_STAGE_OF_STEP[i]
      .map((s) => stagesByStage.get(s))
      .filter((r): r is AiTestdataStageView => !!r)
      .map((r) => (running ? { ...r } : r)),
    planCount: i === 3 ? aiPlanCount.value : undefined,
    // task_current 是生成+运行总体进度百分比（0-100），并非已生成点数，故此处展示为百分数
    progress: i === 3 && taskTotal > 0 ? { pct: job?.task_current ?? 0 } : undefined,
  }));
});

// timeline dot 颜色 / 进行中 loading：finish 绿 / process 蓝(转圈) / error 红 / default 灰
const timelineDotColor = (it: AiTimelineItem) =>
  it.status === "finish" ? "success" : it.status === "process" ? "primary" : it.status === "error" ? "error" : undefined;
const timelineLoading = (it: AiTimelineItem) => it.status === "process";

// 每步状态标签文案 / 主题
const timelineTagText = (it: AiTimelineItem) =>
  it.status === "finish" ? "已完成" : it.status === "process" ? "进行中" : it.status === "error" ? "失败" : "未开始";
const timelineTagTheme = (it: AiTimelineItem) =>
  it.status === "finish" ? "success" : it.status === "process" ? "primary" : it.status === "error" ? "danger" : "default";

// 子阶段（真实 stage 记录）名：仅多子阶段步（生成输入并运行）显示，用于区分生成输入 / 运行参考代码两段
const stageName = (st: AiTestdataStageView) => AI_STATUS_NAMES[st.stage] ?? `阶段 ${st.stage}`;

// 大模型对本题的理解：优先取终态版 result.understanding（失败/跳过时附补充说明），
// 运行期回退到独立列 understanding（参考代码写完后即落库），实现「规划后提前展示」
const aiUnderstanding = computed(() => aiJob.value?.result?.understanding || aiJob.value?.understanding || "");
// 参考代码：优先取终态版 result.reference_code，运行期回退到独立列 reference_code（提前展示）
const aiReferenceCode = computed(() => aiJob.value?.result?.reference_code || aiJob.value?.reference_code || "");
// 当作 markdown 代码块（cpp）交给方 md-preview 渲染，获得语法高亮与统一排版
// （项目参考代码语言默认 C++，与后端 genCfg.ReferenceLanguage 默认一致）
const aiReferenceCodeMarkdown = computed(() =>
  aiReferenceCode.value ? "```cpp\n" + aiReferenceCode.value.trim() + "\n```" : ""
);
// 编译信息：仅存于 result（终态），无独立列，故只在任务结束后展示（挂在「编译参考代码」步）
const aiCompileMessage = computed(() => aiJob.value?.result?.compile_message || "");

// 规划测试点总数：后端在规划完成即写入 plan_total（独立于进度用的 task_total，
// 重试/续跑场景也始终是规划总数，语义稳定）；发起/规划中阶段为 0，不展示
const aiPlanCount = computed(() => aiJob.value?.plan_total ?? 0);

const aiHint = ref("");
const aiJobList = ref<AiTestdataJobView[]>([]);
const aiListLoading = ref(false);
const aiSelectedJobId = ref(0);
const aiJob = ref<AiTestdataJobView | null>(null);
const aiCreating = ref(false);
const aiApplying = ref(false);
const aiApplyDialogVisible = ref(false);
const aiDownloading = ref(false);
// 失败详情弹窗：表格内只展示短标签，完整报错点击后弹窗查看（避免长文本撑宽表格）
const aiErrorDialogVisible = ref(false);
const aiErrorDialogTitle = ref("");
const aiErrorDialogText = ref("");
let aiTimer = -1 as any;
let aiFetchSeq = 0; // 拉取世代计数：放弃任务/卸载组件时自增，使在途请求的响应作废

// 提示词快捷预设：点击后填入文本框。
// 设计约束：这些文案会被当作规划阶段的「用户偏好」叠加在系统提示词之上，
// 因此要（1）彼此独立、（2）不写死与题面冲突的具体数值（如写死 n=10^5 可能与真实限制打架）、
// （3）聚焦"规划侧重"（hint 只在规划阶段生效，不影响生成器/校验器写法）
const hintPresets = [
  {
    label: "边界覆盖",
    text: "覆盖每个约束维度的边界值：n 取最小值（如 n=1）与恰好达到题目数据范围上限两个极端，再补 2~3 个临界值附近的数据",
  },
  {
    label: "最坏构造",
    text: "加入能卡到算法最坏时间复杂度与最大常数的最坏情况构造（如已排序/逆序、全部元素相同、链式结构等），用于区分算法复杂度",
  },
  {
    label: "分级大规模",
    text: "按规模分级铺开：覆盖题目允许的最大规模（如 n/m 取上限）与 2~3 个中等规模随机点，大规模点标注明确规模供生成器使用",
  },
  {
    label: "控制数量",
    text: "测试点数量控制在 10~14 个，减少冗余低价值点，分数集中在边界与最坏构造点",
  },
];

const applyHintPreset = (text: string) => {
  aiHint.value = text;
};

const aiStatusName = computed(() => {
  if (!aiJob.value) return "";
  return AI_STATUS_NAMES[aiJob.value.status] ?? "未知";
});

const aiIsRunning = computed(() => {
  return aiJob.value !== null && aiJob.value.status <= 6;
});

const aiIsFinished = computed(() => {
  return aiJob.value !== null && aiJob.value.status === 7;
});

const aiProgressPercent = computed(() => {
  // task_current 本身就是后端算好的总体进度百分比（生成 0~60、运行至 100），
  // 直接作为进度条百分比，而非再除以测试点总数
  if (!aiJob.value || aiJob.value.task_total <= 0) return 0;
  return Math.max(0, Math.min(100, Math.floor(aiJob.value.task_current)));
});

// 任务表格数据：把 result.tasks 映射为文件元数据列需要的字段（文件名/大小/输出限制）
const aiTasks = computed(() =>
  (aiJob.value?.result?.tasks ?? []).map((t) => ({
    ...t,
    score: t.score ?? 0,
    inFile: `${t.key}.in`,
    inFileSize: t.in_file_size ?? 0,
    outFile: `${t.key}.out`,
    outFileSize: t.out_file_size ?? 0,
    outLimit: t.out_limit ?? 0,
  }))
);

const aiSuccessCount = computed(() => aiTasks.value.filter((t) => t.status === "accepted").length);

const aiHasFailedTasks = computed(() => aiTasks.value.some((t) => t.status !== "accepted"));

// 预览数据是否已过期（R2 存储对象被清理）：过期后下载/应用/重试均需重新生成
const aiFileExpired = computed(() => aiJob.value?.file_expired === true);

// 重试作用域：全部失败测试点（重试所有未通过的点）
const aiFailedKeys = computed(() => aiTasks.value.filter((t) => t.status !== "accepted").map((t) => t.key));

// 当前时间（running 阶段实时计算已用时长）
const aiNow = ref(Date.now());
let aiLastWall = Date.now();
let aiTickTimer = -1 as any;

// 判题机时钟偏差持久化（localStorage，按判题机名的「客户端-判题机」主键）：
// modify_time/start_time 由判题机以其本地时钟写入，与客户端/Web 服务器时钟存在固定偏差（本环境约 +154s）。
// 单次 modify_time 采样会落后（心跳仅 30s、阶段切换才刷新），得到的是偏差下界；这里取历史最大采样逼近
// 真实偏差并跨刷新保留——刷新后首帧就能用已知偏差换算出真实历史耗时，而不是从数据库落盘点（可能陈旧的
// modify_time）重新起算；不同判题机时钟不同，故按判题机名分桶，24h 未见新采样则作废（可能被校时）
const AI_JUDGE_OFFSET_KEY = "dida-ai-judge-clock-offset";
type AiJudgeOffsetEntry = { ahead: number; at: number }; // ahead=判题机领先本地毫秒；at=采样本地时间戳
const loadJudgeAhead = (judger: string): number => {
  try {
    const map = JSON.parse(localStorage.getItem(AI_JUDGE_OFFSET_KEY) ?? "{}") as Record<string, AiJudgeOffsetEntry>;
    const e = map[judger];
    if (!e) return 0;
    return Date.now() - e.at > 24 * 3600 * 1000 ? 0 : e.ahead;
  } catch {
    return 0;
  }
};
const saveJudgeAhead = (judger: string, ahead: number) => {
  try {
    if (!judger || !Number.isFinite(ahead)) return;
    const map = JSON.parse(localStorage.getItem(AI_JUDGE_OFFSET_KEY) ?? "{}") as Record<string, AiJudgeOffsetEntry>;
    const prev = map[judger];
    // 只保留历史最大采样：陈旧的 modify_time 只会得到偏差下界，越新越接近真实偏差
    if (prev && Number.isFinite(prev.ahead) && ahead <= prev.ahead) return;
    map[judger] = { ahead, at: Date.now() };
    localStorage.setItem(AI_JUDGE_OFFSET_KEY, JSON.stringify(map));
  } catch {
    // localStorage 不可用（隐私模式/禁用）时静默降级为会话内推算
  }
};

// 当前任务采用的判题机时钟偏差：拿到任务行后按 judger 从 localStorage 播种，此后每来一个更「新」的
// modify_time 就把测得上限值更新（只在偏差变大——即更接近真实值时更新，保证每秒轮询不抖动），
// 运行阶段耗时据此匀速前进，且刷新后归位真实历史耗时
const aiJudgeAhead = ref(0);
const aiJudgeKnown = ref(false);

// advanceAiNow 推进单调本地时钟：Date.now() 可能因系统校时（NTP/手动调整）回退，
// 导致耗时显示倒流；这里保证 aiNow 只增不减——正常每 100ms 前进，时钟回退时保持不动
const advanceAiNow = () => {
  aiLastWall = Math.max(aiLastWall, Date.now());
  aiNow.value = aiLastWall;
};

// 页面从后台恢复可见时立即刷新一次时间：浏览器会节流后台标签页的定时器，
// 不处理的话切回页面后耗时显示会有一段明显停滞
const handleAiVisibility = () => {
  if (document.visibilityState === "visible") {
    advanceAiNow();
  }
};

const stopAiTick = () => {
  if (aiTickTimer !== -1) {
    clearInterval(aiTickTimer);
    aiTickTimer = -1;
  }
  document.removeEventListener("visibilitychange", handleAiVisibility);
};

// running 时每 100ms tick，驱动「进行中」阶段耗时与 LLM 调用耗时按毫秒级刷新：
// 客户端以 insert_time/start_time 为锚点本地推算（无需等服务端轮询），
// 100ms 采样让 ms 单位的变化肉眼可见、更新节奏均匀；
// 之前 1s 采样叠加 3s 轮询重渲染，观感是忽快忽慢的跳动
watch(aiIsRunning, (running) => {
  if (running) {
    if (aiTickTimer === -1) {
      advanceAiNow();
      aiTickTimer = window.setInterval(() => {
        advanceAiNow();
      }, 100);
      document.addEventListener("visibilitychange", handleAiVisibility);
    }
  } else {
    stopAiTick();
  }
});

// 单调显示值缓存：键为展示项标识（llm:${id} / stage:${id}），值为该项已展示过的最大耗时。
// 客户端推算（本地时钟）与服务端落库值（服务端时钟）之间存在时钟偏差：
// running → success/fail 切换时若直接换用落库值，显示可能倒流。
// 不做精确时钟对齐，只以已展示最大值为下限，保证耗时只增不减
const aiDurationFloor = new Map<string, number>();

const monotonicDuration = (key: string, value: number) => {
  if (!Number.isFinite(value) || value < 0) value = 0;
  const floor = aiDurationFloor.get(key) ?? 0;
  const next = Math.max(floor, value);
  aiDurationFloor.set(key, next);
  return next;
};

// 行级锚点缓存：仅在「无服务端时钟可用」时兜底使用（running 行/阶段的起始锚点，ms）。
// 常规走 liveRunningMs 的服务端减法路径，无需此缓存；此处只是避免个别极端场景下负值长时间钳成 0ms
const aiAnchorMap = new Map<string, number>();

const liveRunningMs = (key: string, startMs: number) => {
  // 判题机时钟偏差路径（首选）：偏差已知且起始时间是判题机时钟时，
  // 用 aiNow + (判题机领先本地的偏差) 换算成判题机当前时间，running 耗时 = 换算后当前 - start_time。
  // 偏差只在新的 modify_time 到来且更大（更接近真实）时更新，更新之间保持恒定 → aiNow 每 100ms 单调前进，
  // 耗时匀速前进；刷新后从 localStorage 播种同一偏差，立即显示真实历史耗时，不受刷新/数据库落盘点影响
  if (aiJudgeKnown.value && Number.isFinite(startMs)) {
    return Math.max(0, aiNow.value + aiJudgeAhead.value - startMs);
  }
  // 兜底：未知偏差时回退到本地锚点（锚点取 min(起始时间, 首次渲染本地时间)，避免负值钳成 0）
  let anchor = aiAnchorMap.get(key);
  if (anchor === undefined) {
    anchor = Number.isFinite(startMs) ? Math.min(startMs, aiNow.value) : aiNow.value;
    aiAnchorMap.set(key, anchor);
  }
  return Math.max(0, aiNow.value - anchor);
};

// 把当前选中的 AI 任务同步到 URL 路径末段（…/judge/ai/:jobId），便于刷新/分享定位到指定历史任务。
// 复用 route.replace 不产生新历史记录，切换历史任务不会污染后退栈；
// 未选中任务（放弃/回到发起区）时删除该路径段，避免遗留已放弃任务的引用
const syncAiJobRoute = (jobId: number) => {
  const raw = route.params.jobId;
  const rawVal = Array.isArray(raw) ? raw[0] : raw;
  const current = rawVal == null ? 0 : Number(rawVal);
  if (current === jobId) return;
  const params = { ...route.params };
  if (jobId > 0) {
    params.jobId = String(jobId);
  } else {
    delete params.jobId;
  }
  router.replace({ name: "manage-problem-judge-ai", params });
};

// 切换/重置任务时清空单调缓存与判题机偏差采样标志（row id 全局唯一，这里只是保险，避免跨任务串号）
watch(aiSelectedJobId, () => {
  aiDurationFloor.clear();
  aiAnchorMap.clear();
  aiJudgeKnown.value = false;
  aiJudgeAhead.value = 0;
  syncAiJobRoute(aiSelectedJobId.value);
});

// 耗时格式化：<1s 用 ms，<60s 用 s，否则 min s
const formatDuration = (ms: number) => {
  if (!ms || ms <= 0) return "0ms";
  if (ms < 1000) return `${Math.round(ms)}ms`;
  if (ms < 60000) return `${(ms / 1000).toFixed(1)}s`;
  const min = Math.floor(ms / 60000);
  const sec = Math.round((ms % 60000) / 1000);
  return sec > 0 ? `${min}min ${sec}s` : `${min}min`;
};

// 阶段耗时：running 用锚点实时推算（客户端时钟偏差安全），否则用后端落库的 duration_ms；
// 经 monotonicDuration 保证切换时显示值不回退
const stageDuration = (st: AiTestdataStageView) => {
  const value = st.status === "running" ? liveRunningMs(`stage:${st.id}`, new Date(st.start_time).getTime()) : st.duration_ms;
  return formatDuration(monotonicDuration(`stage:${st.id}`, value));
};

// 心跳新鲜度：后端每完成一个测试点（或写入阶段文案）都会刷新 modify_time，
// 前端据此区分「正在推进」与「判题机可能已失联」（aiNow 每 100ms tick 驱动刷新）
const lastUpdateAgo = computed(() => {
  if (!aiJob.value?.modify_time) return "";
  const ms = aiNow.value - new Date(aiJob.value.modify_time).getTime();
  if (ms < 0) return "刚刚";
  return formatDuration(ms) + " 前";
});

// 认领时间（本地时区 HH:mm:ss）
const claimTimeText = computed(() => {
  if (!aiJob.value?.judge_time) return "";
  const d = new Date(aiJob.value.judge_time);
  return Number.isNaN(d.getTime()) ? "" : d.toLocaleTimeString("zh-CN", { hour12: false });
});

// 应用=应用所有通过的测试点，失败的点无有效数据、自动剔除（dropKeys=全部失败点）
// 应用按钮禁用：没有任何通过的测试点时不允许应用
const aiApplyDisabled = computed(() => aiSuccessCount <= 0);

// 任务状态对应的 tag 主题：进行中 primary / 完成 success / 失败 danger / 取消 default
const jobTagTheme = (status: number) => {
  if (status === 7) return "success";
  if (status === 8) return "danger";
  return status === 9 ? "default" : "primary";
};

const aiJobTagTheme = computed(() => (aiJob.value ? jobTagTheme(aiJob.value.status) : "primary"));

// 历史任务时间（本地时区 MM-DD HH:mm）
const formatJobTime = (t?: string) => {
  if (!t) return "";
  const d = new Date(t);
  if (Number.isNaN(d.getTime())) return "";
  return d.toLocaleString("zh-CN", {
    hour12: false,
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  });
};

const clearAiTimer = () => {
  if (aiTimer !== -1) {
    clearTimeout(aiTimer);
    aiTimer = -1;
  }
};

// 拉取任务状态，运行中则 1 秒后继续轮询
// aiFetchSeq 为世代计数：放弃任务/卸载组件时自增，使在途请求的过期响应作废
const fetchAiJob = async () => {
  clearAiTimer();
  if (aiSelectedJobId.value <= 0) return;
  const seq = ++aiFetchSeq;
  let res: any;
  try {
    res = await GetJudgeDataAi(aiSelectedJobId.value);
  } catch (e) {
    // 网络瞬时错误不能中断轮询链：静默排下一次，否则界面会永久冻结在旧状态
    console.error(e);
    if (seq !== aiFetchSeq) return;
    aiTimer = setTimeout(fetchAiJob, 3000);
    return;
  }
  // 过期响应（任务已被放弃或组件已卸载）直接丢弃，防止复活轮询
  if (seq !== aiFetchSeq) return;
  if (res.code !== 0) {
    // 运行中任务的瞬时错误不应永久中断轮询：静默排下一次；非运行中才提示并停止
    if (aiJob.value && aiJob.value.status <= 6) {
      aiTimer = setTimeout(fetchAiJob, 3000);
      return;
    }
    ShowErrorTips(globalProperties, res.code);
    return;
  }
  // 捕获判题机时钟偏差：modify_time 即判题机写入的其本地当前时刻，与本地拉取时刻之差即两端时钟偏差。
  // 每次响应都重新测量，但偏差只在测得值更大（更新鲜、更接近真实偏差）时采用并持久化——
  // 既避免每 1s 轮询用陈旧 modify_time 重算导致的锯齿跳动，又保证首次播种/长期任务下逐步逼近真实偏差。
  const jobData = res.data as AiTestdataJobView;
  if (jobData.modify_time) {
    const measured = new Date(jobData.modify_time).getTime() - Date.now();
    const judger = jobData.judger ?? "";
    // 首个响应播种：localStorage 里该判题机的历史最大偏差可立即用于换算，让刷新后耗时归位真实历史值
    if (!aiJudgeKnown.value) {
      aiJudgeAhead.value = loadJudgeAhead(judger);
      aiJudgeKnown.value = true;
    }
    if (Number.isFinite(measured)) {
      const best = Math.max(aiJudgeAhead.value, measured);
      if (best !== aiJudgeAhead.value) {
        aiJudgeAhead.value = best;
        saveJudgeAhead(judger, best);
      }
    }
  }
  // 校验任务归属当前题目：URL/下拉传入的 jobId 若指向其他题目则视为任务不存在，
  // 防止跨题展示（含标程与预览）。理论上前端侧栏/新建只会在本题内产生 jobId。
  if (jobData.problem_id && jobData.problem_id !== problemId) {
    ShowTextTipsError(globalProperties, "任务不存在或不属于当前题目");
    aiFetchSeq++; // 作废后续轮询
    clearAiTimer();
    aiJob.value = null;
    aiSelectedJobId.value = 0; // watch 会同步清空路由 jobId，回到创建区
    return;
  }
  aiJob.value = jobData;
  // 同步刷新历史任务列表里当前任务的 status 标签（运行中也会变化）
  const listIdx = aiJobList.value.findIndex((j) => j.id === aiJob.value!.id);
  if (listIdx >= 0) {
    aiJobList.value[listIdx] = { ...aiJobList.value[listIdx], status: aiJob.value!.status };
  }
  if (aiJob.value.status <= 6) {
    // 1 秒轮询：新 LLM 调用行「首次出现」的延迟从 3 秒降到约 1 秒
    aiTimer = setTimeout(fetchAiJob, 1000);
  }
};

// 拉取历史 AI 生成任务列表，供侧栏/移动端选择器展示与切换。
// 不做自动选中：URL 无 jobId 时默认停留创建界面，查看历史/进行中任务需手动点开
const loadAiJobList = async () => {
  aiListLoading.value = true;
  try {
    const res = await GetJudgeDataAiList(problemId);
    if (res.code !== 0) return;
    aiJobList.value = (res.data as AiTestdataJobView[]) ?? [];
  } catch (e) {
    console.error(e);
    return;
  } finally {
    aiListLoading.value = false;
  }
};

const handleSelectAiJob = (v: any) => {
  const id = Number(v);
  if (id <= 0) {
    // 移动端下拉选择「＋ 新建生成任务」：回到创建界面
    handleNewAi();
    return;
  }
  aiSelectedJobId.value = id;
  // 用列表里这一行的轻量数据同步预填 aiJob，避免 fetch 详情返回前闪现「新建任务」发起区；
  // stages（时间线）等重字段由随后的 fetchAiJob 详细响应补齐
  const picked = aiJobList.value.find((j) => j.id === id);
  if (picked) aiJob.value = { ...picked };
  fetchAiJob();
};

// 打开测试点失败详情弹窗：状态列只显示短标签，完整报错（沙箱状态/失败原因）点击后查看
const showAiTaskError = (row: any) => {
  aiErrorDialogTitle.value = `测试点 ${row.key} 失败详情`;
  const lines: string[] = [];
  if (row.purpose) lines.push(`用途：${row.purpose}`);
  lines.push(`状态：${row.status === "gen_fail" ? "生成失败（gen_fail）" : "运行失败（run_fail）"}`);
  if (row.sandbox_status) lines.push(`沙箱状态：${row.sandbox_status}`);
  if (row.fail_reason) lines.push(`失败原因：\n${row.fail_reason}`);
  aiErrorDialogText.value = lines.join("\n");
  aiErrorDialogVisible.value = true;
};

// 打开 LLM 调用失败详情弹窗：LLM 报错文本可能很长，同样点击查看完整内容
const showAiLlmError = (row: any) => {
  aiErrorDialogTitle.value = `LLM 调用失败详情（模型 ${row.model} · attempt ${row.attempt}）`;
  const lines: string[] = [];
  if (row.task_key) lines.push(`测试点：${row.task_key}`);
  if (row.error) lines.push(row.error);
  aiErrorDialogText.value = lines.join("\n") || "（无错误信息）";
  aiErrorDialogVisible.value = true;
};

// 下载 AI 预览测试数据 zip（后端返回预签名 URL）
const handleDownloadAiZip = async () => {
  if (aiFileExpired.value) {
    // 已标记过期：不再发起请求，直接提示用户重新生成
    ShowTextTipsError(globalProperties, "预览数据已过期，请重新生成");
    return;
  }
  aiDownloading.value = true;
  try {
    const res = await GetAiPreviewZip(aiSelectedJobId.value);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      // 100083：后端发现 R2 对象不存在并已标记过期，刷新任务状态让界面进入「已过期」展示
      if (res.code === 100083) {
        fetchAiJob();
      }
      return;
    }
    const url = res.data as string;
    if (url) {
      // 预签名 zip 为 application/zip：同窗口跳转触发下载，避免 async 回调里的 window.open 被 popup 拦截
      window.location.href = url;
    }
  } finally {
    aiDownloading.value = false;
  }
};

const handleStartAi = async () => {
  aiCreating.value = true;
  try {
    const res = await PostJudgeDataAi(problemId, aiHint.value);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    aiSelectedJobId.value = res.data.id;
    if (res.data.reused === true) {
      // 后端复用了该题已有的进行中任务，本次填写的提示词未生效
      ShowTextTipsError(globalProperties, "该题已有进行中的生成任务，已恢复其进度（本次填写的提示词未生效）");
    } else {
      ShowTextTipsSuccess(globalProperties, "生成任务已创建");
    }
    await fetchAiJob();
    // 刷新历史任务列表，让新任务出现在侧栏中
    loadAiJobList();
  } finally {
    aiCreating.value = false;
  }
};

const handleApplyAi = () => {
  aiApplyDialogVisible.value = true;
};

const handleConfirmApply = async () => {
  aiApplying.value = true;
  try {
    const res = await PostJudgeDataAiApply(aiSelectedJobId.value, aiFailedKeys.value);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      // 100083：预览数据已过期，刷新任务状态让界面进入「已过期」展示
      if (res.code === 100083) {
        fetchAiJob();
      }
      return;
    }
    aiApplyDialogVisible.value = false;
    ShowTextTipsSuccess(globalProperties, "已应用为官方测试数据");
    aiJob.value = null;
    aiSelectedJobId.value = 0;
    // 刷新历史任务列表：自动选中最近一条（即刚应用的这条），展示「已应用」状态
    await loadAiJobList();
  } finally {
    aiApplying.value = false;
  }
};

// 新建生成任务：清空当前选中回到发起区（不取消任何任务，进行中的生成继续在后台跑，
// 由后端 CreateJob 在发起时自动选择复用或新开）
const handleNewAi = () => {
  aiFetchSeq++; // 使在途请求作废，防止旧任务响应复活
  clearAiTimer();
  aiJob.value = null;
  aiSelectedJobId.value = 0;
};

// 放弃当前任务：通知后端取消（停止流水线与 LLM 开销、释放判题机槽位），
// 并清空展示回到发起区（不自动发起，供修改提示语后手动开始生成）
const handleResetAi = async () => {
  aiFetchSeq++; // 使在途请求作废，防止过期响应复活已放弃的任务
  clearAiTimer();
  if (aiSelectedJobId.value > 0) {
    try {
      await PostJudgeDataAiCancel(aiSelectedJobId.value);
    } catch (e) {
      // 取消失败不阻塞本地界面重置（任务可能已结束）
      console.error(e);
    }
  }
  aiJob.value = null;
  aiSelectedJobId.value = 0;
};

// 放弃并重新生成：先取消旧任务，再用当前提示语立即发起一次新的生成
const handleRestartAi = async () => {
  await handleResetAi();
  handleStartAi();
};

// 在当前任务上继续生成：不新开任务，把原任务重置回待认领，
// 判题机在原有时间线上追加新一轮生成（复用规划/标程/已通过测试点）。
// retryKeys 为本次要重新生成的测试点；为空表示重试全部失败的点
const handleRetryAi = async (retryKeys: string[] | null = null) => {
  if (aiSelectedJobId.value <= 0) return;
  aiCreating.value = true;
  try {
    const res = await PostJudgeDataAiRetry(aiSelectedJobId.value, retryKeys ?? []);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    // 续跑沿用同一任务 id，时间线向后扩展
    aiSelectedJobId.value = res.data.id;
    ShowTextTipsSuccess(globalProperties, "已在当前任务上继续生成，时间线将向后扩展（复用规划、参考代码与已通过测试点）");
    await fetchAiJob();
    loadAiJobList();
  } finally {
    aiCreating.value = false;
  }
};

