};

onMounted(async () => {
  if (Array.isArray(route.params.problemKey)) {
    problemKey.value = route.params.problemKey[0];
  } else {
    problemKey.value = route.params.problemKey;
  }
  if (!problemKey.value) {
    ShowTextTipsError(globalProperties, "题目不存在");
    await router.push({ name: "problem" });
    return;
  }

  problemLoading.value = true;
  // 从 URL 路径恢复指定历史任务（…/judge/ai/:jobId，便于刷新/分享定位到某一任务）。
  // 无 jobId 时不做自动选中（默认停留创建界面），仅当路径显式指定了任务才恢复展示
  const rawJob = route.params.jobId;
  const rawJobVal = Array.isArray(rawJob) ? rawJob[0] : rawJob;
  const urlJobId = rawJobVal == null ? 0 : Number(rawJobVal);
  if (Number.isInteger(urlJobId) && urlJobId > 0) {
    aiSelectedJobId.value = urlJobId;
  }
  await loadProblem();
  // 拉取历史任务列表，供侧栏/移动端选择器展示与切换
  if (aiEnabled.value && problemId > 0) {
    await loadAiJobList();
  }
  // URL 指定任务时 loadProblem/loadAiJobList 均不自动拉取，这里补一次，保证刷新/分享进来即展示该任务
  if (aiSelectedJobId.value > 0 && !aiJob.value) {
    await fetchAiJob();
  }
});
</script>

