                  <div class="dida-ai-meta">生成在后台持续进行，可安全离开本页，稍后返回自动恢复进度。</div>
                  <t-button theme="default" @click="handleResetAi">放弃</t-button>
                </t-space>
              </div>

              <!-- 失败区（含"未能生成数据"的优雅跳过：均在理解文本中说明） -->
              <div v-else-if="aiJob?.status === 8">
