                <t-space style="margin-top: 12px" :break-line="isMobile">
                  <t-button theme="primary" @click="handleRetryAi()" :loading="aiCreating"> 继续生成（复用规划与标程，扩展时间线） </t-button>
                  <t-button theme="default" @click="handleRestartAi">全新生成</t-button>
