              <div v-else-if="aiJob?.status === 9">
                <t-alert theme="default" message="该生成任务已被取消，可以重新发起新的生成。" />
                <t-button theme="default" @click="handleRestartAi" style="margin-top: 12px"> 重新发起 </t-button>
              </div>

              </t-card>

            <!-- 生成流水线：常驻贯穿全生命周期，置于「生成任务」之下、「生成结果」之上。
                 发起前整条「未开始」占位（提前感知未来任务）；进行中依次点亮真实阶段（每子阶段带耗时/LLM），
                 第 3 步「生成输入并运行」合并展示 stage5/6 两段并带 (a/X) 生成进度；
                 理解提前出现（挂在「规划测试点」步的 LLM 之后），参考代码/编译信息各自挂在对应步后 -->
            <t-card class="dida-ai-card" title="生成流水线">
              <t-timeline mode="same" label-align="left">
                <t-timeline-item
                  v-for="it in aiTimelineItems"
                  :key="it.title"
                  :loading="timelineLoading(it)"
                  :dot-color="timelineDotColor(it)"
                >
                  <!-- 阶段标题 + 状态 tag（统一放在节点标题后，清晰标识本阶段状态；子阶段行不再重复状态） -->
                  <div class="dida-ai-tl-title">
                    <span class="dida-ai-tl-title-text">{{ it.title }}</span>
                    <t-tag size="small" :theme="timelineTagTheme(it)" variant="light">{{ timelineTagText(it) }}</t-tag>
                  </div>
                  <!-- 测试点总数 + 生成进度（挂在「生成输入并运行」步） -->
                  <div v-if="it.planCount || it.progress" class="dida-ai-meta dida-ai-tl-plan">
                    <template v-if="it.planCount">规划 <strong>{{ it.planCount }}</strong> 个测试点</template>
                    <template v-if="it.progress"
                      ><template v-if="it.planCount"> · </template>生成进度
                      <strong>{{ it.progress.pct }}</strong>%</template
                    >
                  </div>
                  <!-- 未开始占位：阶段描述的提示文案 -->
                  <div
                    v-if="it.stageRecs.length === 0 && it.status === 'default' && !it.planCount"
                    class="dida-ai-meta dida-ai-tl-placeholder"
                  >
                    {{ it.content }}
                  </div>
                  <!-- 各真实子阶段明细：仅有多子阶段（生成输入并运行）的步显示阶段名，单子阶段（规划/撰写/编译）由标题已表达，不再重复 -->
                  <div v-for="st in it.stageRecs" :key="st.id" class="dida-ai-tl-stage">
                    <div class="dida-ai-tl-line">
                      <span v-if="it.stageRecs.length > 1" class="dida-ai-tl-stage-name">{{ stageName(st) }}</span>
                      <span style="margin-left: 6px">{{ stageDuration(st) }}</span>
                      <span v-if="st.message" class="dida-ai-meta" style="margin-left: 6px">{{ st.message }}</span>
                    </div>
                    <t-collapse v-if="st.llm_calls?.length" style="margin-top: 4px">
                      <t-collapse-panel :header="`LLM 调用（${st.llm_calls.length} 次）`">
                        <t-table
                          :data="liveLlmCalls(st.llm_calls)"
                          :columns="llmCallColumns"
                          row-key="id"
                          size="small"
                          vertical-align="top"
                          table-layout="auto"
                          :scroll="{ x: 'max-content' }"
                        />
                      </t-collapse-panel>
                    </t-collapse>
                  </div>
                  <!-- 对本题的理解：挂在「规划测试点」步的 LLM 调用之后 -->
                  <t-collapse v-if="it.step === 0 && aiUnderstanding" style="margin-top: 4px">
                    <t-collapse-panel header="对本题的理解">
                      <div class="dida-ai-understanding">{{ aiUnderstanding }}</div>
                    </t-collapse-panel>
                  </t-collapse>
                  <!-- 参考代码：挂在「撰写参考代码」步的 LLM 调用之后，用项目自带 md-preview 渲染以获语法高亮。
                 codeFoldable=false 让代码块默认展开（md-editor-v3 默认按长度折叠）；外层容器负责限高滚动 -->
                  <t-collapse v-if="it.step === 1 && aiReferenceCode" style="margin-top: 4px">
                    <t-collapse-panel header="参考代码">
                      <div class="dida-ai-tl-code">
                        <md-preview :model-value="aiReferenceCodeMarkdown" :preview-theme="'cyanosis'" :code-foldable="false" />
                      </div>
                    </t-collapse-panel>
                  </t-collapse>
                  <!-- 编译信息：挂在「编译参考代码」步的 LLM 调用之后 -->
                  <t-collapse v-if="it.step === 2 && aiCompileMessage" style="margin-top: 4px">
                    <t-collapse-panel header="编译信息">
                      <pre class="dida-ai-code">{{ aiCompileMessage }}</pre>
                    </t-collapse-panel>
                  </t-collapse>
                </t-timeline-item>
              </t-timeline>
            </t-card>

